solution.code:
import { readFileSync } from "fs";

const n = Number(readFileSync(0, "utf8").trim());

// 長さ 9 の配列を作り、添字から 1〜9 を作る
const row = Array.from({ length: 9 }, (_, i) => n * (i + 1));
console.log(row.join(" "));
